"""Check project legal documents and the distribution paths that include them."""

from pathlib import Path
import unittest
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[1]
NS = {"m": "http://maven.apache.org/POM/4.0.0"}


class LegalMetadataTest(unittest.TestCase):
    def test_supplemental_evidence_preserves_original_bytes_in_git(self):
        attributes = (ROOT / ".gitattributes").read_text()
        self.assertIn("/scripts/third-party-licenses/** -text -whitespace", attributes)

    def test_notice_preserves_copied_lwjgl_license(self):
        notice = (ROOT / "NOTICE.md").read_text()
        self.assertIn("Copyright LWJGL. All rights reserved.", notice)
        self.assertIn((ROOT / "scripts/third-party-licenses/lwjgl.txt").read_text(), notice)

    def test_project_notice(self):
        notice = (ROOT / "NOTICE.md").read_text()
        for required in (
            "Eclipse RDF4J", "https://projects.eclipse.org/projects/technology.rdf4j",
            "https://rdf4j.org", "https://github.com/eclipse-rdf4j/rdf4j",
            "Eclipse Distribution License v1.0", "SPDX-License-Identifier: BSD-3-Clause",
            "Third-party", "Cryptography",
        ):
            self.assertIn(required, notice)
        self.assertNotIn("Eclipse Public License Version 1.0", notice)

    def test_security_uses_confidential_reporting(self):
        policy = (ROOT / "SECURITY.md").read_text()
        self.assertIn("/work_items/new?issue[confidential]=true", policy)
        self.assertIn("https://www.eclipse.org/security/policy/", policy)
        self.assertNotIn("security@", policy)
        self.assertNotIn("<organization>", policy)

    def test_security_preserves_existing_support(self):
        policy = (ROOT / "SECURITY.md").read_text()
        for required in (
            "current release", "latest minor release before the current",
            "latest major release before the current", "on request only", "anything older",
            "4.1.x", "4.0.x", "3.7.x", "3.6.x",
        ):
            self.assertIn(required, policy)

    def test_sdk_includes_project_legal_files(self):
        sdk = ET.parse(ROOT / "assembly/src/main/assembly/sdk.xml").getroot()
        sources = {node.text for node in sdk.findall("files/file/source")}
        self.assertIn("../LICENSE", sources)
        self.assertIn("../NOTICE.md", sources)
        for source in sources:
            if source.startswith("../"):
                self.assertTrue((ROOT / "assembly" / source).is_file(), source)

    def test_onejar_includes_project_legal_files(self):
        pom = ET.parse(ROOT / "assembly/pom.xml").getroot()
        exclusions = {
            node.text for transformer in pom.findall(".//m:transformer", NS)
            if transformer.get("implementation", "").endswith("DontIncludeResourceTransformer")
            for node in transformer.findall("m:resources/m:resource", NS)
        }
        # Every project JAR already carries these files. Remove those copies
        # before adding the canonical ones to avoid duplicate ZIP entries.
        self.assertEqual(exclusions, {"META-INF/LICENSE", "META-INF/NOTICE.md"})
        resources = {
            node.findtext("m:resource", namespaces=NS): node.findtext("m:file", namespaces=NS)
            for node in pom.findall(".//m:transformer", NS)
            if node.get("implementation", "").endswith(".IncludeResourceTransformer")
        }
        self.assertEqual(resources.get("META-INF/LICENSE"), "../LICENSE")
        self.assertEqual(resources.get("META-INF/NOTICE.md"), "../NOTICE.md")
        for source in resources.values():
            self.assertTrue((ROOT / "assembly" / source).is_file(), source)

    def test_modules_include_project_legal_resources(self):
        pom = ET.parse(ROOT / "pom.xml").getroot()
        resources = pom.findall("m:build/m:resources/m:resource", NS)
        legal = next((node for node in resources if node.findtext(
            "m:targetPath", namespaces=NS) == "META-INF"), None)
        self.assertIsNotNone(legal)
        self.assertEqual(legal.findtext("m:directory", namespaces=NS),
                         "${maven.multiModuleProjectDirectory}")
        self.assertEqual(legal.findtext("m:filtering", namespaces=NS), "false")
        includes = {node.text for node in legal.findall("m:includes/m:include", NS)}
        self.assertEqual(includes, {"LICENSE", "NOTICE.md"})
        self.assertTrue(any(node.findtext("m:directory", namespaces=NS)
                            == "${project.basedir}/src/main/resources" for node in resources))

    def test_no_stale_notice_packaging_paths(self):
        for path in ("assembly/pom.xml", "assembly/src/main/assembly/sdk.xml"):
            self.assertNotIn("../notice.md", (ROOT / path).read_text())

    def test_workbench_copies_canonical_notice_without_filtering(self):
        pom = ET.parse(ROOT / "tools/workbench/pom.xml").getroot()
        resources = pom.findall(".//m:execution[m:id='copy-frontend-static']//m:resource", NS)
        legal = next(node for node in resources if node.findtext("m:targetPath", namespaces=NS) == "legal")
        self.assertEqual(legal.findtext("m:directory", namespaces=NS), "${maven.multiModuleProjectDirectory}")
        self.assertEqual(legal.findtext("m:filtering", namespaces=NS), "false")
        self.assertEqual({node.text for node in legal.findall("m:includes/m:include", NS)},
                         {"NOTICE.md", "LICENSE", "edl-v1.0.txt"})

    def test_workbench_generates_notices_from_runtime_closure(self):
        pom = ET.parse(ROOT / "tools/workbench/pom.xml").getroot()
        copy = pom.find(".//m:execution[m:id='resolve-notice-dependencies']", NS)
        self.assertIsNotNone(copy)
        self.assertEqual(copy.findtext("m:phase", namespaces=NS), "prepare-package")
        self.assertEqual(copy.findtext("m:configuration/m:includeScope", namespaces=NS), "runtime")
        generate = pom.find(".//m:execution[m:id='generate-third-party-notices']", NS)
        self.assertIsNotNone(generate)
        self.assertEqual(generate.findtext("m:phase", namespaces=NS), "prepare-package")
        arguments = [node.text for node in generate.findall("m:configuration/m:arguments/m:argument", NS)]
        for required in ("--version", "${project.version}", "--npm-modules", "--java-classpath", "--maven-repo"):
            self.assertIn(required, arguments)
        strict = pom.find("m:profiles/m:profile[m:id='strict-notices']", NS)
        self.assertEqual(strict.findtext("m:properties/m:notices.completeness", namespaces=NS), "--strict")

    def test_workbench_serves_markdown_notices_as_text(self):
        root = ET.parse(ROOT / "tools/workbench/src/main/webapp/WEB-INF/web.xml").getroot()
        mappings = {node.findtext("{*}extension"): node.findtext("{*}mime-type")
                    for node in root.findall("{*}mime-mapping")}
        self.assertEqual(mappings.get("md"), "text/plain")

    def test_workbench_revalidates_version_bundled_notices(self):
        root = ET.parse(ROOT / "tools/workbench/src/main/webapp/WEB-INF/web.xml").getroot()
        patterns = {pattern.text for mapping in root.findall("{*}filter-mapping")
                    if mapping.findtext("{*}filter-name") == "RevalidatedAssetFilter"
                    for pattern in mapping.findall("{*}url-pattern")}
        self.assertIn("/legal/*", patterns)

    def test_server_boot_retains_legal_files_with_custom_resources(self):
        pom = ET.parse(ROOT / "tools/server-boot/pom.xml").getroot()
        resources = pom.findall("m:build/m:resources/m:resource", NS)
        legal = next((node for node in resources if node.findtext("m:targetPath", namespaces=NS) == "META-INF"), None)
        self.assertIsNotNone(legal)
        self.assertEqual({node.text for node in legal.findall("m:includes/m:include", NS)}, {"LICENSE", "NOTICE.md"})

    def test_war_root_retains_project_notices(self):
        pom = ET.parse(ROOT / "pom.xml").getroot()
        war = pom.find("m:build/m:pluginManagement/m:plugins/m:plugin[m:artifactId='maven-war-plugin']", NS)
        resources = war.findall("m:configuration/m:webResources/m:resource", NS)
        self.assertTrue(any(node.findtext("m:targetPath", namespaces=NS) == "META-INF" for node in resources))
        workbench = ET.parse(ROOT / "tools/workbench/pom.xml").getroot()
        resources = workbench.find("m:build/m:plugins/m:plugin[m:artifactId='maven-war-plugin']/m:configuration/m:webResources", NS)
        self.assertEqual(resources.get("combine.children"), "append")


if __name__ == "__main__":
    unittest.main()
